#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int N = 200010;
int n;
vector<int> adj[N];
ll dp[N], sz[N], tiao[N], tt[N];
ll ans;

void dfs1(int u, int fa) {
    sz[u] = 1;
    tiao[u] = 1;
    for (int v : adj[u]) {
        if (v == fa) continue;
        dfs1(v, u);
        sz[u] += sz[v];
        dp[u] += dp[v] + (n - sz[v]) * sz[v] * 2;
        if (u != 1) {
            tiao[fa] += tiao[v];   // 向上传递跳跃信息
        }
        tt[u] += tiao[v];
    }
}

void dfs2(int u, int fa) {
    for (int v : adj[u]) {
        if (v == fa) continue;
        dfs2(v, u);
        // 横向新航道
        ans -= tiao[v] * (tt[u] - tiao[v]);
        if (u != 1) {
            // 纵向新航道
            ans -= tiao[v] * (n - sz[u]) * 2;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    for (int i = 1; i < n; i++) {
